using System;
using Framework.Pathfinding;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.AI.Perception;
using Game.Map;
using UnityEngine;

namespace Game.AI.Tactics
{
    /// <summary>
    /// 敵AIの追跡、迎撃、逃走、帰還戦術を評価する。
    /// </summary>
    /// <remarks>
    /// 本クラスは目的地の評価のみを担当する。
    /// 行動選択や実際の移動処理は行わない。
    /// </remarks>
    public sealed class MazeEnemyTacticalEvaluator
        : IDisposable
    {
        /// <summary>
        /// 戦術評価に使用する敵AIコンテキスト。
        /// </summary>
        private readonly MazeEnemyContext context;

        /// <summary>
        /// 敵自身を起点とする経路距離情報。
        /// </summary>
        private readonly GridDistanceMap<MazeCell>
            selfDistanceMap;

        /// <summary>
        /// 脅威を起点とする経路距離情報。
        /// </summary>
        private readonly GridDistanceMap<MazeCell>
            threatDistanceMap;

        /// <summary>
        /// 縄張り中心を起点とする経路距離情報。
        /// </summary>
        private readonly GridDistanceMap<MazeCell>
            territoryDistanceMap;

        /// <summary>
        /// 地形変更などによる距離情報の無効状態。
        /// </summary>
        private bool isDirty = true;

        /// <summary>
        /// 破棄済みであるか。
        /// </summary>
        private bool isDisposed;

        /// <summary>
        /// 戦術評価に使用するコンテキスト。
        /// </summary>
        public MazeEnemyContext Context => context;

        /// <summary>
        /// 戦術評価システムが利用可能であるか。
        /// </summary>
        public bool IsValid =>
            !isDisposed && context.IsValid;

        /// <summary>
        /// 破棄済みであるか。
        /// </summary>
        public bool IsDisposed => isDisposed;

        /// <summary>
        /// 現在の経路探索開始座標。
        /// </summary>
        /// <remarks>
        /// セル間を移動中の場合は到達予定セルを使用する。
        /// </remarks>
        public Vector2Int Origin =>
            context.IsTraversing
                ? context.TargetCell
                : context.CurrentCell;

        /// <summary>
        /// 戦術評価システムを生成する。
        /// </summary>
        /// <param name="context">敵AIコンテキスト</param>
        /// <exception cref="ArgumentNullException">
        /// コンテキストが指定されていない場合。
        /// </exception>
        /// <exception cref="ArgumentException">
        /// コンテキストが無効な場合。
        /// </exception>
        public MazeEnemyTacticalEvaluator(
            MazeEnemyContext context)
        {
            if (context == null)
            {
                throw new ArgumentNullException(
                    nameof(context));
            }

            if (!context.IsValid)
            {
                throw new ArgumentException(
                    "敵AIコンテキストが無効です。",
                    nameof(context));
            }

            this.context = context;

            selfDistanceMap =
                new GridDistanceMap<MazeCell>(
                    context.Map,
                    context.IsWalkable);

            threatDistanceMap =
                new GridDistanceMap<MazeCell>(
                    context.Map,
                    context.IsWalkable);

            territoryDistanceMap =
                new GridDistanceMap<MazeCell>(
                    context.Map,
                    context.IsWalkable);

            context.Map.CellChanged += HandleCellChanged;
        }

        /// <summary>
        /// 距離情報を必要に応じて更新する。
        /// </summary>
        /// <returns>更新可能な場合はtrue</returns>
        public bool Refresh()
        {
            if (!IsValid)
            {
                return false;
            }

            if (isDirty)
            {
                selfDistanceMap.Clear();
                threatDistanceMap.Clear();
                territoryDistanceMap.Clear();

                isDirty = false;
            }

            if (!selfDistanceMap.IsCalculated ||
                selfDistanceMap.Origin != Origin)
            {
                if (!selfDistanceMap.Calculate(Origin))
                {
                    return false;
                }
            }

            return true;
        }

        /// <summary>
        /// 保持している距離情報を無効化する。
        /// </summary>
        public void Invalidate()
        {
            if (!isDisposed)
            {
                isDirty = true;
            }
        }

        /// <summary>
        /// 認識対象への直接追跡を評価する。
        /// </summary>
        /// <param name="target">対象の観測情報</param>
        /// <param name="evaluation">戦術評価結果</param>
        /// <returns>追跡可能な場合はtrue</returns>
        public bool TryEvaluateChase(
            MazeEnemyTargetObservation target,
            out MazeEnemyTacticalEvaluation evaluation)
        {
            evaluation = default;

            if (!CanEvaluateTarget(
                    target,
                    MazeEnemyTargetType.Player) ||
                !Refresh())
            {
                return false;
            }

            float speed = GetChaseSpeed();

            if (speed <= 0f)
            {
                return false;
            }

            int distance = selfDistanceMap.GetDistance(
                target.LastKnownPosition);

            if (distance < 0)
            {
                return false;
            }

            float arrivalTime = GetArrivalTime(
                distance,
                speed);

            float distanceScore =
                1f / (1f + arrivalTime);

            float score =
                target.Confidence * distanceScore;

            evaluation =
                new MazeEnemyTacticalEvaluation(
                    MazeEnemyTacticalType.Chase,
                    Origin,
                    target.LastKnownPosition,
                    target.LastKnownPosition,
                    distance,
                    arrivalTime,
                    0f,
                    0,
                    target.Confidence,
                    score);

            return true;
        }

        /// <summary>
        /// 観測情報から対象の進行先を予測する。
        /// </summary>
        /// <param name="target">対象の観測情報</param>
        /// <param name="predictionTime">予測時間</param>
        /// <param name="position">予測座標</param>
        /// <param name="distance">予測移動距離</param>
        /// <returns>予測可能な場合はtrue</returns>
        /// <remarks>
        /// 現在の移動方向へ直進すると仮定する。
        /// 壁やマップ境界に到達した場合は予測を停止する。
        /// </remarks>
        public bool TryPredictPosition(
            MazeEnemyTargetObservation target,
            float predictionTime,
            out Vector2Int position,
            out int distance)
        {
            position = default;
            distance = 0;

            if (!IsValid ||
                !target.IsValid ||
                target.Confidence <= 0f ||
                !IsFiniteNonNegative(predictionTime) ||
                !context.IsWalkable(
                    target.LastKnownPosition))
            {
                return false;
            }

            position = target.LastKnownPosition;

            if (target.LastKnownDirection ==
                    Vector2Int.zero ||
                target.LastKnownMoveSpeed <= 0f ||
                predictionTime == 0f)
            {
                return true;
            }

            // マップ寸法を上限として過剰な反復を防ぐ。
            int maxSteps = Mathf.Max(
                context.Map.Width,
                context.Map.Height);

            double predictedDistance =
                (double)target.LastKnownMoveSpeed *
                predictionTime;

            int steps = (int)Math.Min(
                Math.Floor(predictedDistance),
                maxSteps);

            for (int i = 0; i < steps; i++)
            {
                Vector2Int next =
                    position +
                    target.LastKnownDirection;

                if (!context.IsWalkable(next))
                {
                    break;
                }

                position = next;
                distance++;
            }

            return true;
        }

        /// <summary>
        /// 対象への先回り地点を評価する。
        /// </summary>
        /// <param name="target">対象の観測情報</param>
        /// <param name="evaluation">戦術評価結果</param>
        /// <returns>迎撃可能な場合はtrue</returns>
        public bool TryEvaluateIntercept(
            MazeEnemyTargetObservation target,
            out MazeEnemyTacticalEvaluation evaluation)
        {
            evaluation = default;

            if (!CanEvaluateTarget(
                    target,
                    MazeEnemyTargetType.Player) ||
                !target.IsVisible ||
                !Refresh())
            {
                return false;
            }

            float intelligence =
                context.GetParameterValue(
                    MazeEnemyParameter.TacticalIntelligence);

            float predictionTime =
                context.GetParameterValue(
                    MazeEnemyParameter.PredictionTime);

            float speed = GetChaseSpeed();

            if (intelligence <= 0f ||
                speed <= 0f ||
                target.LastKnownMoveSpeed <= 0f)
            {
                return false;
            }

            if (!TryPredictPosition(
                    target,
                    predictionTime,
                    out _,
                    out int predictedDistance) ||
                predictedDistance <= 0)
            {
                return false;
            }

            bool found = false;
            float bestScore = -1f;

            Vector2Int candidate =
                target.LastKnownPosition;

            // 予測経路上の各セルを迎撃候補として評価する。
            for (int i = 1; i <= predictedDistance; i++)
            {
                candidate += target.LastKnownDirection;

                int distance =
                    selfDistanceMap.GetDistance(candidate);

                if (distance < 0)
                {
                    continue;
                }

                float enemyTime = GetArrivalTime(
                    distance,
                    speed);

                float targetTime =
                    i / target.LastKnownMoveSpeed;

                // プレイヤーより遅く到着する候補を除外する。
                if (enemyTime > targetTime)
                {
                    continue;
                }

                float timeAdvantage =
                    Mathf.Clamp01(
                        (targetTime - enemyTime) /
                        Mathf.Max(targetTime, 0.001f));

                float progressScore =
                    (float)i / predictedDistance;

                float score =
                    intelligence *
                    target.Confidence *
                    (0.5f +
                     timeAdvantage * 0.3f +
                     progressScore * 0.2f);

                if (found && score <= bestScore)
                {
                    continue;
                }

                found = true;
                bestScore = score;

                evaluation =
                    new MazeEnemyTacticalEvaluation(
                        MazeEnemyTacticalType.Intercept,
                        Origin,
                        candidate,
                        target.LastKnownPosition,
                        distance,
                        enemyTime,
                        targetTime,
                        0,
                        target.Confidence,
                        score);
            }

            return found;
        }

        /// <summary>
        /// 脅威から離れるための逃走地点を評価する。
        /// </summary>
        /// <param name="threat">脅威の観測情報</param>
        /// <param name="maxTravelDistance">
        /// 逃走候補の最大経路距離
        /// </param>
        /// <param name="evaluation">戦術評価結果</param>
        /// <returns>逃走候補が存在する場合はtrue</returns>
        public bool TryEvaluateEscape(
            MazeEnemyTargetObservation threat,
            int maxTravelDistance,
            out MazeEnemyTacticalEvaluation evaluation)
        {
            evaluation = default;

            if (maxTravelDistance <= 0 ||
                !CanEvaluateTarget(
                    threat,
                    MazeEnemyTargetType.Threat) ||
                !Refresh())
            {
                return false;
            }

            float speed = GetEscapeSpeed();

            if (speed <= 0f)
            {
                return false;
            }

            if (!threatDistanceMap.IsCalculated ||
                threatDistanceMap.Origin !=
                    threat.LastKnownPosition)
            {
                if (!threatDistanceMap.Calculate(
                    threat.LastKnownPosition))
                {
                    return false;
                }
            }

            int currentSafety =
                threatDistanceMap.GetDistance(Origin);

            // 脅威と経路が接続していない場合は逃走不要。
            if (currentSafety < 0)
            {
                return false;
            }

            bool found = false;
            float bestScore = -1f;

            foreach (Vector2Int candidate in
                selfDistanceMap.GetPositionsWithinDistance(
                    maxTravelDistance))
            {
                int distance =
                    selfDistanceMap.GetDistance(candidate);

                if (distance <= 0)
                {
                    continue;
                }

                int safetyDistance =
                    threatDistanceMap.GetDistance(candidate);

                if (safetyDistance <= currentSafety)
                {
                    continue;
                }

                int safetyGain =
                    safetyDistance - currentSafety;

                float safetyScore = Mathf.Clamp01(
                    (float)safetyGain /
                    maxTravelDistance);

                float arrivalTime =
                    GetArrivalTime(distance, speed);

                float travelScore =
                    1f / (1f + arrivalTime);

                float score =
                    threat.Confidence *
                    (safetyScore * 0.8f +
                     travelScore * 0.2f);

                if (found &&
                    (score < bestScore ||
                     (score == bestScore &&
                      distance >= evaluation.Distance)))
                {
                    continue;
                }

                found = true;
                bestScore = score;

                evaluation =
                    new MazeEnemyTacticalEvaluation(
                        MazeEnemyTacticalType.Escape,
                        Origin,
                        candidate,
                        threat.LastKnownPosition,
                        distance,
                        arrivalTime,
                        0f,
                        safetyDistance,
                        threat.Confidence,
                        score);
            }

            return found;
        }

        /// <summary>
        /// 縄張り内への帰還地点を評価する。
        /// </summary>
        /// <param name="evaluation">戦術評価結果</param>
        /// <returns>帰還が必要かつ可能な場合はtrue</returns>
        public bool TryEvaluateReturn(
            out MazeEnemyTacticalEvaluation evaluation)
        {
            evaluation = default;

            if (!Refresh())
            {
                return false;
            }

            float radius =
                context.GetParameterValue(
                    MazeEnemyParameter.TerritoryRadius);

            float territoriality =
                context.GetParameterValue(
                    MazeEnemyParameter.Territoriality);

            float speed =
                context.GetParameterValue(
                    MazeEnemyParameter.MoveSpeed);

            if (territoriality <= 0f || speed <= 0f)
            {
                return false;
            }

            Vector2Int center =
                context.TerritoryCenter;

            if (!territoryDistanceMap.IsCalculated ||
                territoryDistanceMap.Origin != center)
            {
                if (!territoryDistanceMap.Calculate(center))
                {
                    return false;
                }
            }

            int currentDistance =
                territoryDistanceMap.GetDistance(Origin);

            if (currentDistance < 0 ||
                currentDistance <= radius)
            {
                return false;
            }

            bool found = false;
            int bestDistance = int.MaxValue;
            int bestCenterDistance = int.MaxValue;

            Vector2Int bestPosition = default;

            // 縄張り内の到達可能な最寄り地点を探す。
            foreach (Vector2Int candidate in
                territoryDistanceMap.GetPositionsWithinDistance(
                    Mathf.FloorToInt(radius)))
            {
                int distance =
                    selfDistanceMap.GetDistance(candidate);

                if (distance < 0)
                {
                    continue;
                }

                int centerDistance =
                    territoryDistanceMap.GetDistance(candidate);

                if (distance > bestDistance ||
                    (distance == bestDistance &&
                     centerDistance >= bestCenterDistance))
                {
                    continue;
                }

                found = true;
                bestDistance = distance;
                bestCenterDistance = centerDistance;
                bestPosition = candidate;
            }

            if (!found)
            {
                return false;
            }

            float outsideDistance =
                currentDistance - radius;

            float returnPressure =
                Mathf.Clamp01(
                    outsideDistance /
                    Mathf.Max(radius, 1f));

            evaluation =
                new MazeEnemyTacticalEvaluation(
                    MazeEnemyTacticalType.ReturnToTerritory,
                    Origin,
                    bestPosition,
                    center,
                    bestDistance,
                    GetArrivalTime(bestDistance, speed),
                    0f,
                    0,
                    1f,
                    territoriality * returnPressure);

            return true;
        }

        /// <summary>
        /// 指定対象が戦術評価可能であるか確認する。
        /// </summary>
        /// <param name="target">対象の観測情報</param>
        /// <param name="type">必要な対象種類</param>
        /// <returns>評価可能な場合はtrue</returns>
        private bool CanEvaluateTarget(
            MazeEnemyTargetObservation target,
            MazeEnemyTargetType type)
        {
            return IsValid &&
                target.IsValid &&
                target.Type == type &&
                target.Confidence > 0f &&
                context.IsWalkable(
                    target.LastKnownPosition);
        }

        /// <summary>
        /// 追跡時の移動速度を取得する。
        /// </summary>
        /// <returns>セル毎秒の移動速度</returns>
        private float GetChaseSpeed()
        {
            return context.GetParameterValue(
                       MazeEnemyParameter.MoveSpeed) *
                   context.GetParameterValue(
                       MazeEnemyParameter.ChaseSpeedMultiplier);
        }

        /// <summary>
        /// 逃走時の移動速度を取得する。
        /// </summary>
        /// <returns>セル毎秒の移動速度</returns>
        private float GetEscapeSpeed()
        {
            return context.GetParameterValue(
                       MazeEnemyParameter.MoveSpeed) *
                   context.GetParameterValue(
                       MazeEnemyParameter.EscapeSpeedMultiplier);
        }

        /// <summary>
        /// 目的地までの到達時間を計算する。
        /// </summary>
        /// <param name="distance">経路距離</param>
        /// <param name="speed">移動速度</param>
        /// <returns>到達予測時間</returns>
        private float GetArrivalTime(
            int distance,
            float speed)
        {
            if (speed <= 0f)
            {
                return float.PositiveInfinity;
            }

            float remainingDistance = distance;

            // 移動中の場合は現在の区間の残り距離を加える。
            if (context.IsTraversing)
            {
                remainingDistance += Mathf.Clamp01(
                    1f - context.Movement.SegmentProgress);
            }

            return remainingDistance / speed;
        }

        /// <summary>
        /// 数値が有限かつ非負であるか確認する。
        /// </summary>
        /// <param name="value">確認対象の数値</param>
        /// <returns>有効な数値である場合はtrue</returns>
        private static bool IsFiniteNonNegative(
            float value)
        {
            return !float.IsNaN(value) &&
                !float.IsInfinity(value) &&
                value >= 0f;
        }

        /// <summary>
        /// マップのセル変更を処理する。
        /// </summary>
        /// <param name="position">変更された座標</param>
        /// <param name="previous">変更前のセル</param>
        /// <param name="current">変更後のセル</param>
        private void HandleCellChanged(
            Vector2Int position,
            MazeCell previous,
            MazeCell current)
        {
            // 宝石やアイテムの変更では再計算しない。
            if (previous.IsWalkable != current.IsWalkable)
            {
                Invalidate();
            }
        }

        /// <summary>
        /// 戦術評価システムを破棄する。
        /// </summary>
        public void Dispose()
        {
            if (isDisposed)
            {
                return;
            }

            isDisposed = true;

            context.Map.CellChanged -= HandleCellChanged;

            selfDistanceMap.Clear();
            threatDistanceMap.Clear();
            territoryDistanceMap.Clear();
        }
    }
}
